param()

$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest

$NoGui = (
    [Environment]::GetEnvironmentVariable('DEEPSEEK_INSTALL_NO_GUI') -eq '1'
)

Add-Type -AssemblyName System.Windows.Forms

function Write-Utf8NoBom {
    param([string]$Path, [string]$Text)

    [IO.File]::WriteAllText(
        $Path,
        $Text,
        (New-Object Text.UTF8Encoding($false))
    )
}

function Remove-TaggedBlock {
    param(
        [string]$Text,
        [string]$Begin,
        [string]$End
    )

    if ($null -eq $Text) {
        return ''
    }

    $pattern = (
        '(?ms)^[ \t]*' +
        [regex]::Escape($Begin) +
        '.*?^[ \t]*' +
        [regex]::Escape($End) +
        '[ \t]*\r?\n?'
    )

    return [regex]::Replace([string]$Text, $pattern, '')
}

function Test-PowerShellFileSyntax {
    param([string]$Path)

    $tokens = $null
    $parseErrors = $null

    [void][System.Management.Automation.Language.Parser]::ParseFile(
        $Path,
        [ref]$tokens,
        [ref]$parseErrors
    )

    if (($null -ne $parseErrors) -and ($parseErrors.Count -gt 0)) {
        $details = @(
            $parseErrors | ForEach-Object {
                "Line $($_.Extent.StartLineNumber), Col $($_.Extent.StartColumnNumber): $($_.Message)"
            }
        ) -join "`r`n"

        throw "$Path PowerShell syntax check failed:`r`n$details"
    }
}

function Invoke-McpProbe {
    param([string]$ServerPath)

    $initialize = '{"jsonrpc":"2.0","id":1,"method":"initialize","params":{"protocolVersion":"2025-06-18","capabilities":{},"clientInfo":{"name":"hotfix3-installer","version":"1.0"}}}'
    $initialized = '{"jsonrpc":"2.0","method":"notifications/initialized","params":{}}'
    $list = '{"jsonrpc":"2.0","id":2,"method":"tools/list","params":{}}'

    $lines = @(
        $initialize,
        $initialized,
        $list
    ) -join "`r`n"

    $output = $lines |
        & powershell.exe `
            -NoLogo `
            -NoProfile `
            -NonInteractive `
            -ExecutionPolicy Bypass `
            -File $ServerPath

    $responses = @($output)

    if ($responses.Count -lt 2) {
        throw 'MCP probe returned fewer than two responses.'
    }

    $toolResponse = $null

    foreach ($line in $responses) {
        try {
            $candidate = ([string]$line) | ConvertFrom-Json

            if (
                ($null -ne $candidate.id) -and
                ([string]$candidate.id -eq '2')
            ) {
                $toolResponse = $candidate
                break
            }
        }
        catch {}
    }

    if ($null -eq $toolResponse) {
        throw 'MCP probe could not find tools/list response.'
    }

    $names = @(
        $toolResponse.result.tools |
        ForEach-Object { [string]$_.name }
    )

    foreach ($required in @(
        'deepseek_start',
        'deepseek_poll',
        'deepseek_cancel',
        'deepseek_status',
        'deepseek_consult'
    )) {
        if ($required -notin $names) {
            throw "MCP probe missing tool: $required"
        }
    }

    return ($names -join ', ')
}

try {
    $codexHome = if ($env:CODEX_HOME) {
        $env:CODEX_HOME
    } else {
        Join-Path $env:USERPROFILE '.codex'
    }

    $serverDir = Join-Path $codexHome 'deepseek-mcp'
    $serverPath = Join-Path $serverDir 'server.ps1'
    $workerPath = Join-Path $serverDir 'stream-worker.ps1'
    $configPath = Join-Path $codexHome 'config.toml'

    New-Item -ItemType Directory -Path $serverDir -Force | Out-Null

    $timestamp = Get-Date -Format 'yyyyMMdd-HHmmss'
    $backupDir = Join-Path `
        $codexHome `
        "backup-sol-luna-deepseek-hotfix3\$timestamp"

    New-Item -ItemType Directory -Path $backupDir -Force | Out-Null

    foreach ($path in @($serverPath, $workerPath, $configPath)) {
        if (Test-Path -LiteralPath $path -PathType Leaf) {
            Copy-Item `
                -LiteralPath $path `
                -Destination (Join-Path $backupDir ([IO.Path]::GetFileName($path))) `
                -Force
        }
    }

    $skillPath = Join-Path `
        $HOME `
        '.agents\skills\sol-multi-worker-orchestrator\SKILL.md'

    if (Test-Path -LiteralPath $skillPath -PathType Leaf) {
        Copy-Item `
            -LiteralPath $skillPath `
            -Destination (Join-Path $backupDir 'orchestrator-SKILL.md') `
            -Force
    }

    [IO.File]::WriteAllBytes(
        $serverPath,
        [Convert]::FromBase64String('')
    )

    $serverText = Get-Content -Raw -Encoding UTF8 -LiteralPath $serverPath
    $outputEncodingLine = (
        '$OutputEncoding = [Console]::OutputEncoding = ' +
        'New-Object System.Text.UTF8Encoding($false)'
    )
    $rpcInputBlock = @'
$RpcInput = [Console]::OpenStandardInput()
$RpcInputBuffer = New-Object System.Collections.Generic.List[byte]

function Read-Utf8StdinLine {
    while ($true) {
        $value = $RpcInput.ReadByte()

        if ($value -eq -1) {
            if ($RpcInputBuffer.Count -eq 0) {
                return $null
            }

            break
        }

        if ($value -eq 10) {
            break
        }

        if ($value -ne 13) {
            $RpcInputBuffer.Add([byte]$value)
        }
    }

    $bytes = $RpcInputBuffer.ToArray()
    $RpcInputBuffer.Clear()
    return $utf8NoBom.GetString($bytes)
}
'@

    if ($serverText -notmatch [regex]::Escape($outputEncodingLine)) {
        throw 'Embedded MCP server is missing the output-encoding marker.'
    }

    if ($serverText -notmatch '\$RpcInput\s*=') {
        $utf8Marker = (
            '$utf8NoBom = New-Object ' +
            'System.Text.UTF8Encoding($false)'
        )

        if ($serverText -notmatch [regex]::Escape($utf8Marker)) {
            throw 'Embedded MCP server is missing the UTF-8 marker.'
        }

        $serverText = $serverText.Replace(
            $utf8Marker,
            $utf8Marker + "`r`n" + $rpcInputBlock.TrimEnd()
        )
    }

    $serverText = $serverText.Replace(
        '$line = [Console]::In.ReadLine()',
        '$line = Read-Utf8StdinLine'
    )

    $serverText = $serverText.Replace(
        "version = '3.3.0-0813-hotfix3-visible-stream'",
        "version = '3.3.3-0813-hotfix3-utf8-raw'"
    )
    Write-Utf8NoBom -Path $serverPath -Text $serverText

    [IO.File]::WriteAllBytes(
        $workerPath,
        [Convert]::FromBase64String('')
    )

    Test-PowerShellFileSyntax -Path $serverPath
    Test-PowerShellFileSyntax -Path $workerPath

    $toolNames = Invoke-McpProbe -ServerPath $serverPath

    # Keep the direct routing from Hotfix2.
    [Environment]::SetEnvironmentVariable(
        'DEEPSEEK_NETWORK_MODE',
        'direct',
        [EnvironmentVariableTarget]::User
    )

    # Update only our MCP block, preserving all unrelated Codex settings.
    $configText = if (Test-Path -LiteralPath $configPath -PathType Leaf) {
        [string](
            Get-Content -Raw -Encoding UTF8 -LiteralPath $configPath
        )
    } else {
        ''
    }

    foreach ($pair in @(
        @('# >>> SOL_DEEPSEEK_MCP >>>', '# <<< SOL_DEEPSEEK_MCP <<<'),
        @('# >>> SOL_MULTI_WORKER_DEEPSEEK_MCP >>>', '# <<< SOL_MULTI_WORKER_DEEPSEEK_MCP <<<'),
        @('# >>> SOL_MULTI_WORKER_0813 >>>', '# <<< SOL_MULTI_WORKER_0813 <<<'),
        @('# >>> SOL_MULTI_WORKER_0813_HOTFIX1 >>>', '# <<< SOL_MULTI_WORKER_0813_HOTFIX1 <<<'),
        @('# >>> SOL_MULTI_WORKER_0813_HOTFIX2 >>>', '# <<< SOL_MULTI_WORKER_0813_HOTFIX2 <<<'),
        @('# >>> SOL_MULTI_WORKER_0813_HOTFIX3 >>>', '# <<< SOL_MULTI_WORKER_0813_HOTFIX3 <<<')
    )) {
        $configText = Remove-TaggedBlock `
            -Text $configText `
            -Begin $pair[0] `
            -End $pair[1]
    }

    $serverTomlPath = $serverPath.Replace('\', '/').Replace('"', '\"')

    $block = @"

# >>> SOL_MULTI_WORKER_0813_HOTFIX3 >>>
[mcp_servers.sol_deepseek_v4]
command = "powershell.exe"
args = ["-NoLogo", "-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass", "-File", "$serverTomlPath"]
enabled = true
required = false
startup_timeout_sec = 15
tool_timeout_sec = 660

[mcp_servers.sol_deepseek_v4.tools.deepseek_start]
approval_mode = "auto"

[mcp_servers.sol_deepseek_v4.tools.deepseek_poll]
approval_mode = "auto"

[mcp_servers.sol_deepseek_v4.tools.deepseek_status]
approval_mode = "auto"

[mcp_servers.sol_deepseek_v4.tools.deepseek_consult]
approval_mode = "auto"
# <<< SOL_MULTI_WORKER_0813_HOTFIX3 <<<
"@

    Write-Utf8NoBom `
        -Path $configPath `
        -Text ($configText.TrimEnd() + "`r`n" + $block.Trim() + "`r`n")

    if (Test-Path -LiteralPath $skillPath -PathType Leaf) {
        $skillText = [string](
            Get-Content -Raw -Encoding UTF8 -LiteralPath $skillPath
        )

        $skillText = Remove-TaggedBlock `
            -Text $skillText `
            -Begin '<!-- DEEPSEEK_VISIBLE_STREAM_BEGIN -->' `
            -End '<!-- DEEPSEEK_VISIBLE_STREAM_END -->'

        $streamBlock = [Text.Encoding]::UTF8.GetString(
            [Convert]::FromBase64String('')
        )

        Write-Utf8NoBom `
            -Path $skillPath `
            -Text ($skillText.TrimEnd() + "`r`n`r`n" + $streamBlock.Trim() + "`r`n")
    }

    $message = @"
Hotfix 3.3 安装成功：DeepSeek 可见流式模式与原始 UTF-8 MCP 输入已启用。

DeepSeek API：
  stream=true
  SSE=true
  stream_options.include_usage=true

Codex 中新增工具：
  $toolNames

推荐路径：
  deepseek_start
      ↓ 立即返回 job_id
  deepseek_poll(wait_seconds=5)
      ↓
  queued / connecting / waiting_for_inference
      ↓
  thinking（显示 reasoning_chars，不泄露原始思维链）
      ↓
  answering（显示 answer_chars + 部分最终答案）
      ↓
  completed（完整答案 + token usage）
      ↓
  Sol 验证和综合

注意：
Codex 当前公开实现并不能可靠显示 MCP notifications/progress，
所以 Hotfix3 使用“后台 SSE + 5 秒轮询”的方式避免黑盒等待。

DeepSeek 仍为 direct；Luna Worker 未修改。

请完全退出并重启 Codex / ChatGPT。

测试：
“Sol 总控。用 DeepSeek V4 Pro Max 分析这个问题，使用可见流式模式，
每 5 秒轮询一次，阶段变化时告诉我进度，完成后你再综合。”

备份：
$backupDir
"@

    if (-not $NoGui) {
        [System.Windows.Forms.MessageBox]::Show(
            $message,
            'DeepSeek Visible Stream Hotfix 3',
            [System.Windows.Forms.MessageBoxButtons]::OK,
            [System.Windows.Forms.MessageBoxIcon]::Information
        ) | Out-Null
    }

    Write-Host $message -ForegroundColor Green
}
catch {
    $message = (
        "安装失败：$($_.Exception.Message)`r`n`r`n" +
        "不会删除聊天记录，也不会修改 Codex Luna Worker。"
    )

    if (-not $NoGui) {
        [System.Windows.Forms.MessageBox]::Show(
            $message,
            'DeepSeek Visible Stream Hotfix 3',
            [System.Windows.Forms.MessageBoxButtons]::OK,
            [System.Windows.Forms.MessageBoxIcon]::Error
        ) | Out-Null
    }

    Write-Host $message -ForegroundColor Red
    exit 1
}
